return items.map(item => {
  // Get data from the 'Edit Fields' node
  const input = item.json;

  let name = "";
  let email = "";

  // 1. Parse the 'From' field to separate Name and Email
  // Input: "Md tanjimul Islam <islammdtanjimul95@gmail.com>"
  if (input.From) {
    const match = input.From.match(/(.*)<(.+)>/);
    if (match) {
      name = match[1].trim().replace(/(^"|"$)/g, "");
      email = match[2].trim();
    } else {
      // Fallback if there's no bracketed email
      email = input.From.trim();
      name = input.From.trim();
    }
  }

  // 2. Return with the exact keys you requested
  return {
    json: {
      "From": name,
      "email": email,
      "Subject": input.Subject || "",
      "Body": input.body || ""
    }
  };
});
